/**
 * Exposes service payment options via render props.
 * Use this to determine which payment scenario to render without reading the service entity directly.
 *
 * Payment scenarios:
 * - `isOnline=true, isInPerson=false, isDeposit=false` → Pay now only (Due now = total)
 * - `isOnline=true, isInPerson=false, isDeposit=true, canPayFullUpfront=false` → Pay now + security deposit
 * - `isOnline=true, isInPerson=false, isDeposit=true, canPayFullUpfront=true` → Radio: Pay deposit now / Pay in full now
 * - `isOnline=true, isInPerson=true` → Radio: Pay Online / Pay on Arrival
 * - `isOnline=false, isInPerson=true` → Pay on arrival only
 *
 * @component
 * Note: This component renders no visible DOM element. It is a flags-only data
 * component — use `asChild` with a render function to consume the flags.
 * For the actual split amounts (deposit / pay-later), use `Payment.PayNow` and
 * `Payment.PayLater`.
 *
 * @example
 * ```tsx
 * <Payment.ServiceOptions asChild>
 *   {({ isOnline, isInPerson, isDeposit, canPayFullUpfront }) => (
 *     // render the correct payment scenario
 *   )}
 * </Payment.ServiceOptions>
 * ```
 */
